const userRequestTargets = `-- name: UserRequestTargets :many
SELECT DISTINCT target_public_key FROM telemetry_requests WHERE user_id = $1
`

func (q *Queries) UserRequestTargets(ctx context.Context, userID uuid.UUID) ([][]byte, error) {
	rows, err := q.db.Query(ctx, userRequestTargets, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := [][]byte{}
	for rows.Next() {
		var target_public_key []byte
		if err := rows.Scan(&target_public_key); err != nil {
			return nil, err
		}
		items = append(items, target_public_key)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
